let contract;
try { contract = JSON.parse(String(inputs.contract ?? "")); } catch { throw new Error("The accepted creative contract is invalid."); }
if (!contract || contract.schemaVersion !== 1 || !contract.copy || !contract.brief || !contract.selectedDirection) throw new Error("The accepted creative contract is incomplete.");
const version = String(inputs.version ?? "").trim();
if (!["original", "revision"].includes(version)) throw new Error("Version must be original or revision.");
if (version === "original" && contract.kind !== "hero") throw new Error("Original layouts require an accepted hero contract.");
if (version === "revision" && contract.kind !== "revision") throw new Error("Revision layouts require an accepted revision contract.");
const heroBytes = await media.bytes(inputs.hero);
const heroInfo = await media.info(inputs.hero);
const allowedImageMimes = ["image/png", "image/jpeg", "image/webp", "image/avif"];
if (!allowedImageMimes.includes(heroInfo.mimeType)) throw new Error(`Hero MIME type ${heroInfo.mimeType || "unknown"} is not supported.`);
if (heroBytes.length === 0) throw new Error("The accepted hero is empty.");
const exact = (name, value, max) => {
  if (typeof value !== "string" || value.length === 0) throw new Error(`${name} is required in the creative contract.`);
  if (value.length > max) throw new Error(`${name} must be ${max} characters or fewer before composing formats.`);
  return value;
};
const productName = exact("Product name", contract.copy.productName, 120);
const headline = exact("Headline", contract.copy.headline, 120);
const cta = exact("CTA", contract.copy.cta, 80);
const wrapExact = (value, maxColumns, maxLines, label) => {
  const lines = [];
  let remaining = value;
  while (remaining.length > 0) {
    const newline = remaining.indexOf("\n");
    if (newline >= 0 && newline < maxColumns) {
      lines.push(remaining.slice(0, newline + 1));
      remaining = remaining.slice(newline + 1);
      continue;
    }
    if (remaining.length <= maxColumns) { lines.push(remaining); remaining = ""; continue; }
    let cut = maxColumns;
    while (cut > 0 && !/\s/.test(remaining[cut])) cut -= 1;
    if (cut === 0) throw new Error(`${label} contains a word longer than ${maxColumns} characters. Add a word break before composing formats.`);
    lines.push(remaining.slice(0, cut + 1));
    remaining = remaining.slice(cut + 1);
  }
  if (lines.length > maxLines) throw new Error(`${label} needs ${lines.length} lines but the layout supports ${maxLines}. Shorten the copy before composing formats.`);
  return lines;
};
const heroDataUri = `data:${heroInfo.mimeType};base64,${toBase64(heroBytes)}`;
const textElement = (x, y, size, lineHeight, value, maxColumns, maxLines, label, fill) => ({ name: "text", attributes: { x, y, fill, "font-family": "Arial, Helvetica, sans-serif", "font-size": size, "font-weight": 600, "xml:space": "preserve" }, children: wrapExact(value, maxColumns, maxLines, label).map((line, index) => ({ name: "tspan", attributes: { x, dy: index === 0 ? 0 : lineHeight }, content: line })) });
const artboard = (height, headlineY, imageY, imageHeight, ctaY, headlineColumns) => [
  { name: "metadata", content: "Directed Campaign Kit. System font fallback: Arial, Helvetica, sans-serif. The embedded photograph uses the accepted hero bytes." },
  { name: "rect", attributes: { x: 0, y: 0, width: 1080, height, fill: "#172022" } },
  { name: "rect", attributes: { x: 0, y: 0, width: 24, height, fill: "#66734f" } },
  textElement(80, 86, 34, 42, productName, 44, 2, "Product name", "#dce3d4"),
  textElement(80, headlineY, 58, 68, headline, headlineColumns, 4, "Headline", "#f1f3ec"),
  { name: "image", attributes: { x: 80, y: imageY, width: 920, height: imageHeight, href: heroDataUri, preserveAspectRatio: "xMidYMid meet" } },
  { name: "line", attributes: { x1: 80, y1: ctaY - 70, x2: 1000, y2: ctaY - 70, stroke: "#66734f", "stroke-width": 2 } },
  textElement(80, ctaY, 32, 40, cta, 50, 2, "CTA", "#dce3d4")
