await output("portrait_elements", artboard(1350, 170, 300, 820, 1240, 30));
await output("story_elements", artboard(1920, 190, 380, 1240, 1790, 28));

const MAX_RECORD_BYTES = 16 * 1024 * 1024;
const allowedImageMimes = ["image/png", "image/jpeg", "image/webp", "image/avif"];
const readImage = async (ref, label) => {
  const bytes = await media.bytes(ref);
  const info = await media.info(ref);
