  if (bytes.length === 0) throw new Error(`${label} is empty.`);
  return bytes;
};
let contract;
try { contract = JSON.parse(String(inputs.contract ?? "")); } catch { throw new Error("The accepted creative contract is invalid."); }
const version = String(inputs.version ?? "").trim();
if (!["original", "revision"].includes(version)) throw new Error("Version must be original or revision.");
const source = await readImage(inputs.hero, "Accepted hero");
const portrait = await readImage(inputs.portrait, "4:5 PNG");
const story = await readImage(inputs.story, "9:16 PNG");
if (portrait.mimeType !== "image/png" || portrait.width !== 1080 || portrait.height !== 1350) throw new Error("The 4:5 PNG must be exactly 1080×1350.");
if (story.mimeType !== "image/png" || story.width !== 1080 || story.height !== 1920) throw new Error("The 9:16 PNG must be exactly 1080×1920.");
const portraitSvgBytes = rawSvg(inputs.portrait_svg_raw, "4:5 SVG");
const storySvgBytes = rawSvg(inputs.story_svg_raw, "9:16 SVG");
const payload = (item) => ({ mimeType: item.mimeType, width: item.width, height: item.height, data: toBase64(item.bytes) });
const svgPayload = (bytes, width, height) => ({ mimeType: "image/svg+xml", width, height, data: toBase64(bytes) });
const artifacts = { source: payload(source), portrait: payload(portrait), story: payload(story), portraitSvg: svgPayload(portraitSvgBytes, 1080, 1350), storySvg: svgPayload(storySvgBytes, 1080, 1920), contract };
let record;
if (version === "original") {
  if (!contract || contract.schemaVersion !== 1 || contract.kind !== "hero" || !contract.brief || !contract.selectedDirection || !contract.copy) throw new Error("Original layouts require a complete accepted hero contract.");
  record = { schemaVersion: 1, brief: contract.brief, references: { role: contract.brief.referenceRole, use: contract.brief.referenceUse, ignore: contract.brief.referenceIgnore }, selectedDirection: contract.selectedDirection, approvedCopy: contract.copy, acceptedVersion: "original", original: artifacts };
} else {
  let original;
  try { original = JSON.parse(await media.text(inputs.original_record)); } catch { throw new Error("The original campaign record file is invalid. Retry the original layout or reopen a valid record."); }
  if (!original || original.schemaVersion !== 1 || original.acceptedVersion !== "original" || !original.original || original.revision) throw new Error("Revision layouts require the unchanged original-only campaign record.");
  if (!contract || contract.schemaVersion !== 1 || contract.kind !== "revision" || !contract.parentContract || !contract.revisionRequest) throw new Error("Revision layouts require a complete child contract.");
  record = { ...original, acceptedVersion: "revision", revision: { ...artifacts, request: contract.revisionRequest } };
}
const recordText = JSON.stringify(record);
const recordBytes = new TextEncoder().encode(recordText);
if (recordBytes.length > MAX_RECORD_BYTES) throw new Error(`The campaign record is ${recordBytes.length} bytes and exceeds the 16 MiB portable record limit. Reduce source file sizes and retry; no artifact was dropped.`);
const [heroRef, portraitRef, storyRef, portraitSvgRef, storySvgRef, recordFile] = await Promise.all([
  media.toImage(source.bytes, { mimeType: source.mimeType }),
  media.toImage(portrait.bytes, { mimeType: "image/png" }),
  media.toImage(story.bytes, { mimeType: "image/png" }),
  media.toDocument(portraitSvgBytes, { mimeType: "image/svg+xml", filename: `${version}-portrait.svg` }),
  media.toDocument(storySvgBytes, { mimeType: "image/svg+xml", filename: `${version}-story.svg` }),
  media.toDocument(recordBytes, { mimeType: "application/json", filename: "directed-campaign.json" })
]);
await output("hero", heroRef);
await output("portrait", portraitRef);
await output("story", storyRef);
await output("portrait_svg", portraitSvgRef);
await output("story_svg", storySvgRef);
await output("contract", JSON.stringify(contract));
await output("record", JSON.stringify({ schemaVersion: 1, acceptedVersion: record.acceptedVersion, productName: record.brief.productName, headline: record.approvedCopy.headline, cta: record.approvedCopy.cta, hasRevision: record.acceptedVersion === "revision", portableRecord: "record_file" }));
await output("record_file", recordFile);
await output("phase", version === "original" ? "campaign_ready" : "complete");

let value = inputs.value;
if (typeof value === "string") {
  const trimmed = value.trim();
  if (trimmed.startsWith("{")) {
    try { value = JSON.parse(trimmed); } catch { value = { type: "image", uri: trimmed }; }
